@startuml

class BusRoute {
  + RouteNumber : int
}

class Bus {
  + LicencePlate : string
  + IsInRepairShop : boolean
}

class Driver {
  + DriverID : int
  + Name : string
  + IsOnSickLeave : boolean
}

class Assignment {
  + Date : date
  + Shift : ShiftType
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

BusRoute "1" -- "*" Assignment : has
Bus "1" -- "*" Assignment : is assigned to
Driver "1" -- "*" Assignment : is assigned to

@enduml

